INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q16636394', '1936 uprising in Spanish Guinea', 'The 1936 uprising in Spanish Guinea was an armed conflict over the control of Spanish Guinea (present-day Equatorial Guinea) during the course of the Spanish Civil War, fought between the republican and nationalist forces between September and October 1936. The nationalists initially took control of Fernando Po on 19 September, later seizing control of the rest of the colony after receiving reinforcements in October.', 1936, NULL, NULL, NULL, NULL, NULL, 'year', '1936', 41, 'https://en.wikipedia.org/wiki/1936_uprising_in_Spanish_Guinea'),
